const originals=$('Receber parecer').all();
const results=$input.all();
return originals.map((item,index)=>({json:item.json,pairedItem:{item:Math.max(0,results.findIndex(result=>result.json.post_id===item.json.post_id))}}));

const original=$('Receber parecer').item.json;
if(!Number.isSafeInteger(original.post_id)||!Array.isArray(original.findings)||!original.findings.length||original.findings.length>30||original.findings.some(f=>typeof f?.claim!=='string'||!f.claim.trim())) throw Error('Parecer editorial inválido.');
const html=typeof $json.data==='string'&&$json.statusCode===200?$json.data:'';
const text=html.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/\s+/g,' ');
const source="https://noticias.stf.jus.br/postsnoticias/stf-concede-prisao-domiciliar-temporaria-ao-ex-presidente-jair-bolsonaro";
const sentence=text.match(/Bolsonaro foi condenado na Ação Penal \(AP\) 2668 a 27 anos e três meses de prisão/i)?.[0];
const grant=text.match(/Alexandre de Moraes, do Supremo Tribunal Federal \(STF\), concedeu prisão domiciliar humanitária ao ex-presidente da República Jair Bolsonaro/i)?.[0];
const date=text.match(/24\/03\/2026\s+\d{2}:\d{2}/)?.[0];
const findings=original.findings.map(({claim,status:editorStatus,sourceId,quote})=>{
  const evidence=[];
  let status='pendente';
  if (/pena de 27 anos e 3 meses/i.test(claim)&&sentence) evidence.push({url:source,excerpt:sentence,scope:'pena de 27 anos e 3 meses'});
  if (/^Bolsonaro cumpre prisão domiciliar humanitária desde março de 2026\.$/i.test(claim)&&grant&&date) {
    evidence.push({url:source,excerpt:grant,scope:'concessão da prisão domiciliar'}, {url:source,excerpt:date,scope:'data do comunicado'});
    status='parcial';
  }
  const attributed=editorStatus==='sustentada'&&typeof sourceId==='string'&&sourceId.trim()&&typeof quote==='string'&&quote.trim();
  const action=editorStatus==='divergente'?'apurar_divergencia':attributed?'atribuir_ou_omitir':'omitir_ou_apurar';
  return {claim,status,action,evidence,editorEvidence:attributed?{sourceId,quote}:null,reason:status==='parcial'?'O comunicado confirma a concessão em março. A continuidade até a data da pauta precisa de evidência adicional.':evidence.length?'O documento confirma a pena. O vínculo com o despacho de novembro continua pendente.':'Nenhuma regra encontrou evidência primária suficiente para a afirmação completa.'};
});
const google=$('Consultar Google Fact Check').all().map(item=>item.json).filter(item=>item.post_id===original.post_id).map(({claim_index,status,http_status,candidates})=>({claim_index,status,http_status,candidates}));
return {json:{googleFactCheck:google,post_id:original.post_id,decision:original.findings.some(f=>f.status==='divergente')?'reter_para_apuracao':'devolver_para_ajuste',modelCalls:0,officialSource:{url:source,statusCode:$json.statusCode??null},findings}};
